_choice_pid() {
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_signal() {
    _helper_kill_signals
}

_choice_signal_number() {
    _helper_kill_signals | gawk -F'\t' '{ print $2 "\t" $1 }'
