_helper_kill_signals() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i < NF; i++) {
            if ($i ~ /^[0-9]+\)$/ && $(i + 1) ~ /^SIG[A-Z][A-Z0-9]*$/) {
                num = $i
                sub(/\)$/, "", num)
                print $(i + 1) "\t" num
            }
        }
    }'
}
